/**
 * NEW RECONSTRUCTION. Not the original generator.
 *
 * The API validator names `scripts/gen-validator.mjs` and the MCP validator names
 * `workers/mcp/scripts/build-validator.ts`, both reading `view-plan.schema.json`.
 * None of those files is in either intake. The schema survives only as the
 * `schema31` literal inside each generated file.
 *
 * This module recompiles that embedded schema with the pinned ajv and rebuilds
 * each file. `--check` compares the result with the recovered bytes and writes
 * nothing. The fixed header and helper text below are copied from the recovered
 * files; only the validator body is produced by ajv.
 */
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const Ajv2020 = require("ajv/dist/2020").default;
const standaloneCode = require("ajv/dist/standalone").default;

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");

export const AJV_VERSION = require("ajv/package.json").version;
export const AJV_OPTIONS = Object.freeze({ allErrors: true, code: Object.freeze({ source: true, esm: true }) });

export const TARGETS = Object.freeze({
  api: {
    path: "recovered-source/worker/src/generated/view-plan.validator.js",
    sha256: "44eb9707472fa910840048adf431199ce9ca2044cbddb1cca1242239f3f3ca25",
    generator: "scripts/gen-validator.mjs",
  },
  mcp: {
    path: "recovered-other/secondary-mcp-dev/worker/src/generated/view-plan-validator.js",
    sha256: "a6065680fd5b829dd3825aa61cb19280ee3c3abec84f456599c6732d2609ebb3",
    generator: "workers/mcp/scripts/build-validator.ts",
  },
});

const API_PRELUDE = `// @generated by scripts/gen-validator.mjs from view-plan.schema.json. Do not edit.

const __ucs2length = (str) => {
  let length = 0;
  for (let pos = 0; pos < str.length; ) {
    length++;
    const value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < str.length && (str.charCodeAt(pos) & 0xfc00) === 0xdc00) pos++;
  }
  return length;
};
const __equal = (a, b) => {
  if (a === b) return true;
  if (!a || !b || typeof a !== "object" || typeof b !== "object") return false;
  if (Array.isArray(a)) return Array.isArray(b) && a.length === b.length && a.every((x, i) => __equal(x, b[i]));
  if (Array.isArray(b)) return false;
  const ka = Object.keys(a);
  return ka.length === Object.keys(b).length && ka.every((k) => Object.hasOwn(b, k) && __equal(a[k], b[k]));
};
`;

const MCP_HEADER = `// biome-ignore-all lint: generated file
// biome-ignore-all format: generated file
// GENERATED by workers/mcp/scripts/build-validator.ts from packages/contracts/schemas/view-plan.schema.json.
// Do not edit. Regenerate with: pnpm --filter @secondary/mcp gen:validator
`;

// The API file has no runtime require(): each ajv runtime import is replaced by the inlined helper above.
const API_INLINED = Object.freeze([
  ['require("ajv/dist/runtime/ucs2length").default', "__ucs2length"],
  ['require("ajv/dist/runtime/equal").default', "__equal"],
]);

/** @param {string} text */
export const sha256 = (text) => createHash("sha256").update(text).digest("hex");

/** @param {string} source @returns {unknown} */
export function extractEmbeddedSchema(source) {
  const marker = "const schema31 = ";
  const start = source.indexOf(marker);
  if (start < 0) throw new Error("schema31 literal not found");
  const from = start + marker.length;
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = from; i < source.length; i += 1) {
    const c = source[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (c === "\\") escaped = true;
      else if (c === '"') inString = false;
    } else if (c === '"') inString = true;
    else if (c === "{") depth += 1;
    else if (c === "}") {
      depth -= 1;
      if (depth === 0) return JSON.parse(source.slice(from, i + 1));
    }
  }
  throw new Error("schema31 literal is not terminated");
}

/** @param {unknown} schema */
export function compileBody(schema) {
  const ajv = new Ajv2020({ ...AJV_OPTIONS, code: { ...AJV_OPTIONS.code } });
  return standaloneCode(ajv, ajv.compile(/** @type {object} */ (schema)));
}

/** @param {unknown} schema */
export function componentTypes(schema) {
  const s = /** @type {{ properties: { components: { items: { oneOf: { $ref: string }[] } } } }} */ (schema);
  return s.properties.components.items.oneOf.map((x) => x.$ref.replace("#/$defs/", ""));
}

/** @param {unknown} schema */
export function generateApi(schema) {
  let body = compileBody(schema);
  for (const [from, to] of API_INLINED) {
    if (!body.includes(from)) throw new Error(`ajv output no longer contains ${from}`);
    body = body.split(from).join(to);
  }
  return API_PRELUDE + body;
}

/** @param {unknown} schema */
export function generateMcp(schema) {
  return `${MCP_HEADER}${compileBody(schema)}\nexport const COMPONENT_TYPES = ${JSON.stringify(componentTypes(schema))};\n`;
}

export const GENERATE = Object.freeze({ api: generateApi, mcp: generateMcp });

/** @param {"api" | "mcp"} name @param {string} [source] */
export function check(name, source) {
  const target = TARGETS[name];
  const recovered = source ?? readFileSync(join(root, target.path), "utf8");
  const regenerated = GENERATE[name](extractEmbeddedSchema(recovered));
  let firstDiff = -1;
  if (regenerated !== recovered) {
    firstDiff = 0;
    while (firstDiff < regenerated.length && regenerated[firstDiff] === recovered[firstDiff]) firstDiff += 1;
  }
  return {
    name,
    path: target.path,
    recoveredSha256: sha256(recovered),
    regeneratedSha256: sha256(regenerated),
    pinnedSha256: target.sha256,
    identical: regenerated === recovered,
    firstDiff,
    regenerated,
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const out = process.argv.includes("--out") ? process.argv[process.argv.indexOf("--out") + 1] : null;
  let ok = true;
  console.log(`ajv ${AJV_VERSION} Ajv2020 ${JSON.stringify(AJV_OPTIONS)}`);
  for (const name of /** @type {const} */ (["api", "mcp"])) {
    const r = check(name);
    const pinned = r.recoveredSha256 === r.pinnedSha256;
    ok &&= r.identical && pinned;
    console.log(`${name}\t${r.identical ? "identical" : `differs at ${r.firstDiff}`}\trecovered ${r.recoveredSha256}${pinned ? "" : " (not the pinned bytes)"}\tregenerated ${r.regeneratedSha256}\t${r.path}`);
    if (out) {
      mkdirSync(out, { recursive: true });
      writeFileSync(join(out, r.path.split("/").pop() ?? name), r.regenerated);
    }
  }
  process.exit(ok ? 0 : 1);
}
